        product_variations[p['id']] = {}
        for v in p['variations']:
            vid = v['id']
            img = v.get('image', {})
            img_id = img.get('id', None)
            product_variations[p['id']][vid] = img_id
            print(f"  Product {p['id']} ({p['name']}): variation {vid} -> image {img_id}")

# Count total sales per product per variation from orders
sales = {}  # {product_id: {variation_id: total_qty}}
for o in orders:
    for item in o.get('line_items', []):
        pid = item.get('product_id')
        vid = item.get('variation_id', 0)
        qty = item.get('quantity', 1)
        if pid not in sales:
            sales[pid] = {}
        sales[pid][vid] = sales[pid].get(vid, 0) + qty

# Find best-selling variation for each product
best = {}
for pid, var_sales in sales.items():
    best_vid = max(var_sales, key=var_sales.get)
    best[pid] = best_vid
    print(f"Product {pid}: best-selling variation {best_vid} (qty: {var_sales[best_vid]})")

# Check that best-selling variation is within this product's variations
for pid, best_vid in best.items():
    imgs = product_variations.get(pid, {})
    img_id = imgs.get(best_vid)
    if img_id:
        print(f"Product {pid}: update main image to image ID {img_id} (from variation {best_vid})")
    else:
        print(f"WARNING: Product {pid}, variation {best_vid} has no image!")

# Build batch update payload
# woo_products_batch_update expects {"create": [], "update": [...], "delete": []}
updates = []
for pid, best_vid in best.items():
    imgs = product_variations.get(pid, {})
