        updates.append({
            "id": pid,
            "images": [{"id": img_id}]
        })

print(f"\nBatch updates: {len(updates)} products")
for u in updates:
    print(f"  Product {u['id']}: images = {u['images']}")

# Write updates for the next step
with open('/tmp/updates.json', 'w') as f:
    json.dump(updates, f)
